class Solution:
    def biggestBillboard(self, heights: List[int]) -> int:
        n = len(heights)
        left, stack = [-1] * n, []
        for i in range(n):
            while stack and heights[stack[-1]] >= heights[i]:
                stack.pop()
            left[i] = stack[-1] if stack else -1
            stack.append(i)
        best, stack = 0, []
        for i in range(n - 1, -1, -1):
            while stack and heights[stack[-1]] >= heights[i]:
                stack.pop()
            right = stack[-1] if stack else n
            best = max(best, heights[i] * (right - left[i] - 1))
            stack.append(i)
        return best

