class Solution {
    public long biggestBillboard(int[] heights) {
        int n = heights.length;
        int[] left = new int[n], stack = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && heights[stack[top - 1]] >= heights[i]) top--;
            left[i] = top > 0 ? stack[top - 1] : -1;
            stack[top++] = i;
        }
        long best = 0;
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && heights[stack[top - 1]] >= heights[i]) top--;
            int right = top > 0 ? stack[top - 1] : n;
            best = Math.max(best, (long) heights[i] * (right - left[i] - 1));
            stack[top++] = i;
        }
        return best;
    }
}

